// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }
    function testFuzz_property(address actor, uint256 targetBlock, bytes32 guess) public {
        // keep actor nonzero and give it enough Ether to lock two guesses (1 ether per lock)
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        // admissibly restrict the target block to a valid non-genesis block number
        targetBlock = bound(targetBlock, 1, type(uint64).max);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // put the current block after the target block, so the hash is available and past
        uint256 settleBlock = targetBlock + 2;
        vm.roll(settleBlock);

        bytes32 answer = blockhash(targetBlock);
        // need a nonzero blockhash to exercise the mismatch/no-op case
        vm.assume(answer != 0);
        // ensure the locked guess actually mismatches the answer, the no-op case
        vm.assume(guess != answer);

        bool ok = true;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(ok, "settle must no-op for a stale nonzero blockhash mismatch");
    }
}
